import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def adjust_due_date(due_date):
    due = parse(due_date)
    if due.weekday() == 6:  # Sunday
        due += timedelta(days=1)
    return due


def calculate_late_fee(return_date, due_date, item_type):
    due = adjust_due_date(due_date)
    if return_date == "-":
        return_date = parse("2024-03-20")  # Replace with actual asof date from input

    days_late = (parse(return_date) - due).days

    if days_late <= 0:
        return 0.0
    else:
        fee = days_late * RATE[item_type]
        return min(fee, 10.0)


def main():
    lines = sys.stdin.read().splitlines()
    totals = {}
    asof_date = parse(lines[0].split()[1])

    for line in lines[1:]:
        if not line.strip():
            continue
        member, item_type, due_date, return_date = line.split()
        fee = calculate_late_fee(return_date, due_date, item_type)
        totals[member] = totals.get(member, 0.0) + fee

    for member in sorted(totals.keys()):
        print(f"{member} {totals[member]:.2f}")
    print(f"total {sum(totals.values()):.2f}")


if __name__ == "__main__":
    main()
